import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.Tracer;

public class ObservabilityDemoService {
    private static final Logger log = LoggerFactory.getLogger(ObservabilityDemoService.class);
    private final Counter requestCounter;
    private final Tracer tracer;

    public ObservabilityDemoService(MeterRegistry registry, Tracer tracer) {
        this.requestCounter = registry.counter("app.requests.total", "service", "demo");
        this.tracer = tracer;
    }

    public void processOrder(String orderId) {
        requestCounter.increment();
        Span span = tracer.spanBuilder("processOrder").startSpan();
        try (var scope = span.makeCurrent()) {
            MDC.put("orderId", orderId);
            MDC.put("traceId", span.getSpanContext().getTraceId());
            log.info("Processing order execution started.");
            // Business logic execution...
        } catch (Exception e) {
            span.recordException(e);
            log.error("Failed to process order: {}", orderId, e);
            throw e;
        } finally {
            span.end();
            MDC.clear();
        }
    }
}
